"""Data-quality report for the generated SYNTHETIC dataset (reports/data_quality.md)."""
import argparse
from pathlib import Path

import pandas as pd

from movrec import DATA_DIR, PROJECT_ROOT
from movrec.assumptions import load_assumptions

BANNER = (
    "> **SYNTHETIC DATA.** Every row was generated by `src/movrec/generator` from the documented "
    "assumptions in `config/assumptions.yaml`. Nothing here is real customer data, and numbers below "
    "describe the generator, not the real business."
)
TRUCK_PREFIX = "truck_"


def load(data_dir: Path) -> dict[str, pd.DataFrame]:
    data_dir = Path(data_dir)
    return {
        "services": pd.read_csv(data_dir / "services.csv"),
        "customers": pd.read_csv(data_dir / "customers.csv"),
        "bookings": pd.read_csv(data_dir / "bookings.csv", parse_dates=["booking_ts", "move_date"]),
        "lines": pd.read_csv(data_dir / "booking_services.csv"),
        "segments": pd.read_csv(data_dir / "_hidden" / "segments.csv"),
    }


def _table(df: pd.DataFrame, floatfmt: str = "{:.2f}") -> str:
    df = df.copy()
    for c in df.columns:
        if pd.api.types.is_float_dtype(df[c]):
            df[c] = df[c].map(floatfmt.format)
    header = "| " + " | ".join(map(str, df.columns)) + " |"
    sep = "|" + "---|" * len(df.columns)
    rows = ["| " + " | ".join(map(str, r)) + " |" for r in df.itertuples(index=False)]
    return "\n".join([header, sep, *rows])


def _pct(x: float) -> str:
    return f"{100 * x:.1f}%"


def build_report(data_dir: Path = DATA_DIR) -> str:
    d = load(data_dir)
    b, lines, cust, seg = d["bookings"], d["lines"], d["customers"], d["segments"]
    addons = lines[~lines["service_id"].str.startswith(TRUCK_PREFIX)]
    n_addons = addons.groupby("booking_id").size().reindex(b["booking_id"]).fillna(0).astype(int)
    b = b.assign(n_addons=n_addons.to_numpy(), month=b["move_date"].dt.to_period("M").astype(str))
    out = ["# Data-quality report", "", BANNER, ""]

    # --- overview
    out += ["## Overview", "",
            f"- Bookings: {len(b):,}  |  customers: {len(cust):,}  |  cart lines: {len(lines):,}",
            f"- Move dates: {b['move_date'].min():%Y-%m-%d} to {b['move_date'].max():%Y-%m-%d}",
            f"- Catalog: {len(d['services'])} recommendable services "
            f"({d['services']['unit'].nunique()} product families incl. truck)",
            ""]

    # --- cold start
    first = b.groupby("customer_id")["booking_ts"].transform("min") == b["booking_ts"]
    one_booking = (cust["n_bookings"] == 1).mean()
    by_type = cust.groupby("customer_type")["n_bookings"].apply(lambda s: (s == 1).mean())
    out += ["## Cold start", "",
            f"- Customers with exactly one booking: **{_pct(one_booking)}**",
            f"- Bookings that are the customer's first: **{_pct(first.mean())}**",
            "- Single-booking share by customer type: "
            + ", ".join(f"{k} {_pct(v)}" for k, v in by_type.items()),
            "", _table(cust["n_bookings"].clip(upper=5).value_counts().sort_index()
                       .rename_axis("bookings per customer (5 = 5+)").reset_index(name="customers")), ""]

    # --- cart size
    size = b.groupby("move_type")["n_addons"].describe()[["mean", "25%", "50%", "75%", "max"]]
    hist = b["n_addons"].clip(upper=12).value_counts().sort_index()
    out += ["## Add-ons per booking (excluding truck)", "",
            _table(size.reset_index()), "",
            _table((hist / len(b)).map(_pct).rename_axis("add-on lines (12 = 12+)").reset_index(name="share")), ""]

    # --- popularity long tail
    pop = addons["service_id"].value_counts()
    share = (pop / len(b)).rename("bookings with it")
    out += ["## Service frequency (long tail)", "",
            f"- Most common: `{pop.index[0]}` in {_pct(share.iloc[0])} of bookings; "
            f"least common: `{pop.index[-1]}` in {_pct(share.iloc[-1])}.",
            f"- Top 10 services cover {_pct(pop.head(10).sum() / pop.sum())} of add-on lines.",
            "", _table(share.map(_pct).rename_axis("service").reset_index()), ""]

    zero = d["services"].query("pricing == 'free'")["id"].tolist()
    out += [f"- $0 items logged (free per company policy, still recommendable): {', '.join(zero)}. "
            "They add no revenue, so revenue-weighted metrics should treat them separately.", ""]

    # --- combinations
    carts = addons.sort_values("service_id").groupby("booking_id")["service_id"].agg(tuple)
    combo_counts = carts.value_counts()
    out += ["## Combinations", "",
            f"- Distinct add-on carts: {len(combo_counts):,} across {len(carts):,} non-empty carts",
            f"- Carts whose exact combination appears only once: {_pct((combo_counts == 1).sum() / len(carts))}",
            f"- Bookings with no add-ons at all: {_pct((b['n_addons'] == 0).mean())}", ""]

    # --- seasonality
    monthly = b.groupby("month").size().rename("bookings").reset_index()
    cal = b.assign(m=b["move_date"].dt.month)
    peak = cal["m"].between(5, 8).mean()
    out += ["## Seasonality", "",
            f"- Moves in May-Aug: {_pct(peak)} (assumption target ~41%); "
            f"May-Sep: {_pct(cal['m'].between(5, 9).mean())} (target ~half)",
            f"- Weekend moves: {_pct(b['is_weekend'].mean())}",
            "", _table(monthly), ""]

    # --- lead time
    lead = b.groupby("move_type")["lead_time_days"].describe()[["50%", "mean", "max"]]
    out += ["## Lead time (days from booking to move)", "",
            f"- Same/next-day bookings: {_pct((b['lead_time_days'] <= 1).mean())}",
            "", _table(lead.reset_index(), "{:.1f}"), ""]

    # --- prices vs KB
    A = load_assumptions()
    kb = A["labor_hours_range"]
    res = b[b["move_type"] == "local_residential"]
    hrs = res.groupby("home_size")["labor_hours"].median()
    price = res.groupby("home_size")["base_price"].median()
    rows = [{"home_size": h, "KB hours": f"{kb[h][0]}-{kb[h][1]}", "median generated hours": hrs[h],
             "median base price ($)": price[h]} for h in ["studio", "1br", "2br", "3br", "4br_plus"] if h in hrs]
    out += ["## Price check against company knowledge-base ranges (local residential)", "",
            "Generated hours include extra time for stairs and heavy items, which the KB ranges exclude, "
            "so medians sit at or slightly above the KB range. Base price also includes travel time "
            "and payment surcharge.", "", _table(pd.DataFrame(rows)), "",
            f"- Total price, all bookings: median ${b['total_price'].median():,.0f}, "
            f"90th percentile ${b['total_price'].quantile(0.9):,.0f}", ""]

    # --- status
    out += ["## Status", "", _table(b["status"].value_counts(normalize=True).map(_pct)
                                    .rename_axis("status").reset_index(name="share")), ""]

    # --- hidden segments (diagnostics only)
    sm = b[["booking_id", "move_date"]].merge(seg, on="booking_id")
    sm["season"] = sm["move_date"].dt.month.map(
        lambda m: "summer (Jun-Aug)" if m in (6, 7, 8) else ("fall (Sep-Nov)" if m in (9, 10, 11)
                  else ("winter (Dec-Feb)" if m in (12, 1, 2) else "spring (Mar-May)")))
    mix = pd.crosstab(sm["segment"], sm["season"], normalize="columns").map(_pct)
    out += ["## Hidden segment mix by season (DIAGNOSTICS ONLY)", "",
            "The recommender never sees these labels. Shown to confirm the season shift between "
            "train and test periods is real.", "", _table(mix.reset_index()), ""]
    return "\n".join(out)


def main(argv=None) -> None:
    parser = argparse.ArgumentParser(description="Write the data-quality report.")
    parser.add_argument("--data", type=Path, default=DATA_DIR)
    parser.add_argument("--out", type=Path, default=PROJECT_ROOT / "reports" / "data_quality.md")
    args = parser.parse_args(argv)
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(build_report(args.data))
    print(f"wrote {args.out}")


if __name__ == "__main__":
    main()
